begin;
select plan(25);
\ir fixtures/captures.sql.inc
set local role cadence_command;
select pg_temp.as_actor(1);
select lives_ok($$select private.create_private_capture('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',null,'Synthetic hidden title','Synthetic confidential original marker','personal_draft',array['editorial_reuse','excerpt_release']::private.source_purpose[],false,true,null)$$,'creator captures a private text revision');
select is(private.create_private_capture('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',null,'Synthetic hidden title','Synthetic confidential original marker','personal_draft',array['editorial_reuse','excerpt_release']::private.source_purpose[],false,true,null)->>'replayed','true','capture retry returns the same receipt');
select is(private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic hidden title'),1,'editorial_reuse')->>'body','Synthetic confidential original marker','creator reads exact revision');
select throws_ok($$select private.create_private_capture('20000000-0000-4000-8000-000000000001',gen_random_uuid(),null,'unconfirmed','unconfirmed client note','client_confidential',array['editorial_reuse']::private.source_purpose[],false,true,null)$$,'P0001','INVALID_INPUT','client-confidential captures require explicit authority');
select throws_ok($$select private.create_private_capture('20000000-0000-4000-8000-000000000001',gen_random_uuid(),null,'unconfirmed','unconfirmed data','personal_draft',array['editorial_reuse']::private.source_purpose[],false,false,null)$$,'P0001','INVALID_INPUT','capture requires acknowledgement of admitted data');
select throws_ok($$update private.sources set title = 'bypass' where id = pg_temp.capture_id('Synthetic hidden title')$$,'42501',null,'even creator cannot bypass immutable revisions by direct update');
select pg_temp.as_actor(2);
select is((select count(*)::integer from private.sources),0,'second owner cannot list creator-private metadata');
select is((select count(*)::integer from private.source_revisions),0,'second owner cannot read private revision text');
select is(jsonb_array_length(private.search_private_library('20000000-0000-4000-8000-000000000001','sources','confidential',null,20,'editorial_reuse')->'items'),0,'search does not reveal another owner original');
select throws_ok($$select private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic hidden title'),1,'editorial_reuse')$$,'P0001','SOURCE_ACCESS_DENIED','known private ID does not bypass ownership');
select throws_ok($$select private.recover_orphaned_source('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic hidden title'),1,1,'10000000-0000-4000-8000-000000000002','creator_departed')$$,'P0001','SOURCE_ACCESS_DENIED','another owner cannot recover an active creator source');
select pg_temp.as_actor(1);
select lives_ok($$select private.release_reviewed_excerpt('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic hidden title'),1,1,'Synthetic reviewed public text',array['10000000-0000-4000-8000-000000000002']::uuid[],array['editorial_reuse']::private.source_purpose[],true)$$,'creator explicitly reviews and releases an excerpt');
select pg_temp.as_actor(2);
select is(private.read_reviewed_excerpt('20000000-0000-4000-8000-000000000001',pg_temp.excerpt_id('Synthetic reviewed public text'),'editorial_reuse')->>'body','Synthetic reviewed public text','recipient reads reviewed text only');
select ok(not (private.read_reviewed_excerpt('20000000-0000-4000-8000-000000000001',pg_temp.excerpt_id('Synthetic reviewed public text'),'editorial_reuse') ?| array['sourceId','title','creatorId','sourceUrl','filename']),'excerpt DTO has no original metadata');
select is((select count(*)::integer from private.sources),0,'excerpt release does not grant original metadata');
select throws_ok($$select source_id from private.source_excerpts$$,'42501',null,'direct column access cannot reveal excerpt lineage');
select is(jsonb_array_length(private.search_private_library('20000000-0000-4000-8000-000000000001','excerpts','confidential',null,20,'editorial_reuse')->'items'),0,'excerpt search does not search unselected original text');
select is(jsonb_array_length(private.search_private_library('20000000-0000-4000-8000-000000000001','excerpts','reviewed',null,20,'editorial_reuse')->'items'),1,'excerpt search includes selected reviewed text');
select throws_ok($$select private.read_reviewed_excerpt('20000000-0000-4000-8000-000000000001',pg_temp.excerpt_id('Synthetic reviewed public text'),'analytics')$$,'P0001','SOURCE_ACCESS_DENIED','excerpt permission is purpose scoped');
select pg_temp.as_actor(5);
select throws_ok($$select private.create_private_capture('20000000-0000-4000-8000-000000000001',gen_random_uuid(),null,'viewer','viewer capture','personal_draft',array['editorial_reuse']::private.source_purpose[],false,true,null)$$,'P0001','ACCESS_DENIED','viewer cannot capture through command');
select pg_temp.as_actor(8);
select throws_ok($$select private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic hidden title'),1,'editorial_reuse')$$,'P0001','ACCESS_DENIED','cross-tenant source ID denies before metadata read');
select pg_temp.as_actor(1);
select lives_ok($$select private.revoke_source_sharing('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic hidden title'),1,1)$$,'custodian revokes all original and excerpt reuse');
select pg_temp.as_actor(2);
select throws_ok($$select private.read_reviewed_excerpt('20000000-0000-4000-8000-000000000001',pg_temp.excerpt_id('Synthetic reviewed public text'),'editorial_reuse')$$,'P0001','SOURCE_ACCESS_DENIED','revocation immediately blocks released excerpt');
select pg_temp.as_actor(1);
select throws_ok($$select private.release_reviewed_excerpt('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic hidden title'),1,1,'stale',array['10000000-0000-4000-8000-000000000002']::uuid[],array['editorial_reuse']::private.source_purpose[],true)$$,'P0001','VERSION_CONFLICT','stale access version cannot resurrect revoked sharing');
reset role;
select ok(not exists(select 1 from private.access_audit_events where row_to_json(access_audit_events)::text like '%confidential original marker%')
  and not exists(select 1 from private.access_command_receipts where row_to_json(access_command_receipts)::text like '%confidential original marker%'),'audits and receipts exclude capture plaintext');
select * from finish();
rollback;
